class Api{
 static final cache=<String,Map<String,dynamic>>{};
 static Future<Map<String,dynamic>> request(String path,{bool refresh=false,String method='GET',Map<String,dynamic>?body,String?token,bool auth=false})async{
  final key='${auth?'auth':'data'}:$path';
  if(method=='GET'&&!refresh&&cache[key]!=null)return cache[key]!;
  final urls=auth?['$authRoot/$path.php']:['$root/$path','$legacyRoot/$path'];
  Object? last;
  for(final url in urls){final c=HttpClient()..connectionTimeout=const Duration(seconds:15);try{final q=method=='GET'?await c.getUrl(Uri.parse(url)):await c.postUrl(Uri.parse(url));q.headers.set('accept','application/json');if(token!=null)q.headers.set('authorization','Bearer $token');if(body!=null){q.headers.contentType=ContentType.json;q.write(jsonEncode(body));}final r=await q.close().timeout(const Duration(seconds:25));final raw=await utf8.decoder.bind(r).join();final decoded=raw.isEmpty?<String,dynamic>{}:Map<String,dynamic>.from(jsonDecode(raw));if(r.statusCode<200||r.statusCode>=300)throw ApiException('${decoded['error']??'The service is temporarily unavailable. Please try again.'}');if(method=='GET'&&!auth)cache[key]=decoded;return decoded;}catch(e){last=e;}finally{c.close();}}
  if(last is ApiException)throw last;throw const ApiException('Content is temporarily unavailable. Please try again.');
 }
 static Future<Map<String,dynamic>> auth(String path,{Map<String,dynamic>?body,String?token})=>request(path,method:body==null?'GET':'POST',body:body,token:token,auth:true);
}
class ApiException implements Exception{final String message;const ApiException(this.message);@override String toString()=>message;}
Future<Map<String,dynamic>> googleAccount()async{final service=GoogleSignIn(scopes:const['email','profile'],serverClientId:googleServerClientId);await service.signOut();final account=await service.signIn();if(account==null)throw const ApiException('Google sign-in was cancelled.');final auth=await account.authentication;if(auth.idToken==null)throw const ApiException('Google did not return a valid identity token.');final result=await Api.auth('google-login',body:{'credential':auth.idToken});final user=Map<String,dynamic>.from(result['user']);Store.scope='${user['id']}';await Store.set('user',user);await Store.set('token','${result['token']}');return user;}
class Store{
 static String scope='guest';
 static String key(String k)=>['prefs','results','active'].contains(k)?'${k}_$scope':k;
 static Future<SharedPreferences> get p=>SharedPreferences.getInstance();
 static Future<Map<String,dynamic>?> map(String k)async{final s=(await p).getString(key(k));return s==null?null:jsonDecode(s);}
 static Future<List<dynamic>> list(String k)async{final s=(await p).getString(key(k));return s==null?[]:jsonDecode(s);}
 static Future<String?> string(String k)async{final s=(await p).getString(key(k));return s==null?null:'${jsonDecode(s)}';}
 static Future<void> set(String k,Object v)async=>(await p).setString(key(k),jsonEncode(v));
 static Future<void> del(String k)async=>(await p).remove(key(k));
}
class Data{
 final Map<String,dynamic> config;final List<Map<String,dynamic>> exams,tests,syllabi;
 Data(this.config,this.exams,this.tests,this.syllabi);
 static Future<Data> load({bool refresh=false})async{final v=await Future.wait(['site-main.json','exams.json','tests.json','exam-syllabus.json'].map((x)=>Api.request(x,refresh:refresh)));return Data(v[0],List<Map<String,dynamic>>.from(v[1]['exams']),List<Map<String,dynamic>>.from(v[2]['tests']),List<Map<String,dynamic>>.from(v[3]['syllabi']));}
}
